cd /testbed && rustc --edition=2021 -g -L dependency=target/debug/deps --extern tokio=target/debug/deps/libtokio-2ecfcbc5cd5841c0.rlib --extern tokio_test=target/debug/deps/libtokio_test-ca1ab3d75cdb1834.rlib -o /tmp/tokio-broadcast-closed-repro - <<'RS'
use tokio::sync::broadcast;

fn main() {
    let (tx, rx) = broadcast::channel::<u32>(4);
    drop(tx);
    let mut rx_clone = rx.resubscribe();
    drop(rx);
    println!("try_recv after resubscribe: {:?}", rx_clone.try_recv());
    let mut recv = tokio_test::task::spawn(rx_clone.recv());
    println!("recv first poll: {:?}", recv.poll());
    println!("recv second poll: {:?}", recv.poll());
}
RS
/tmp/tokio-broadcast-closed-repro

cd /testbed && peeky probe . --config /dev/stdin --build --at tokio/tests/sync_broadcast.rs:513 --capture rx_resub.next,rx_resub.shared --old 'fn resubscribe_lagged() {
