    tx.send(1).unwrap();
    tx.send(2).unwrap();' --new 'fn resubscribe_lagged() {
    let (tx, mut rx) = broadcast::channel(1);
    tx.send(1).unwrap();
    tx.send(2).unwrap();
    drop(tx);' --timeout 180 -- --exact resubscribe_lagged --nocapture <<'JSON'
