cd /testbed && patch -p1 <<'PATCH'
--- a/tokio/tests/sync_broadcast.rs
+++ b/tokio/tests/sync_broadcast.rs
@@ -518,3 +518,29 @@
     assert_empty!(rx);
     assert_empty!(rx_resub);
 }
+
+#[test]
+fn resubscribe_closed() {
+    for &capacity in &[1, 2, 4] {
+        for sent in 0..=2 * capacity {
+            let (tx, rx) = broadcast::channel(capacity);
+            for value in 0..sent {
+                assert_ok!(tx.send(value));
+            }
+            drop(tx);
+
+            let mut rx_try = rx.resubscribe();
+            let mut rx_async = rx.resubscribe();
+            drop(rx);
+
+            for _ in 0..2 {
+                assert_closed!(rx_try.try_recv());
+                assert_eq!(
+                    assert_ready_err!(task::spawn(rx_async.recv()).poll()),
+                    broadcast::error::RecvError::Closed
+                );
+            }
+            assert_closed!(rx_try.resubscribe().try_recv());
+        }
+    }
+}
PATCH
cargo test -p tokio --test sync_broadcast --features full resubscribe_closed -- --exact

cd /testbed && patch -p1 <<'PATCH'
--- a/tokio/src/sync/broadcast.rs
+++ b/tokio/src/sync/broadcast.rs
@@ -667,7 +667,12 @@
     tail.rx_cnt = tail.rx_cnt.checked_add(1).expect("overflow");

-    let next = tail.pos;
+    // The closing message is stored at the previous position.
+    let next = if tail.closed {
+        tail.pos.wrapping_sub(1)
+    } else {
+        tail.pos
+    };

     drop(tail);

     Receiver { shared, next }
@@ -881,9 +886,9 @@

-        self.next = self.next.wrapping_add(1);
-
         if slot.closed {
             return Err(TryRecvError::Closed);
         }

+        self.next = self.next.wrapping_add(1);
+
         Ok(RecvGuard { slot })
     }
@@ -898,6 +903,9 @@
     /// in the queue of the current receiver. Consider the following example.
     ///
+    /// If the channel is closed, the new receiver will immediately return a
+    /// `Closed` error when receiving.
+    ///
     /// # Examples
     ///
     /// ```
     /// use tokio::sync::broadcast;
PATCH
set -o pipefail && cargo test -p tokio --test sync_broadcast --features full 2>&1 | tail -45

